import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 3.0, 'max': 4, 'flags': ['max', 'n']})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 4, 'mean': 4.5, 'max': 6, 'flags': ['max', 'n']})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 3.6666666666666665, 'max': 5, 'flags': ['max', 'n']})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'mean': 7.0, 'max': 10, 'flags': ['max', 'n']})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 4.666666666666667, 'max': 6, 'flags': ['max', 'n']})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 2.0, 'max': 2, 'flags': ['max', 'n']})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 3.5, 'max': 5, 'flags': ['max', 'n']})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 3, 'mean': 6.0, 'max': 9, 'flags': ['max', 'n']})

